package com.fitconnect.notification.api; import com.fitconnect.notification.domain.*; import java.time.LocalDateTime; public record NotificationResponse(Long id,Long userId,String email,NotificationType type,String subject,String content,LocalDateTime sentDate,NotificationStatus status){public static NotificationResponse from(Notification n){return new NotificationResponse(n.getId(),n.getUserId(),n.getEmail(),n.getType(),n.getSubject(),n.getContent(),n.getSentDate(),n.getStatus());}}
